mapper.select:
SELECT sd.setmeal_id, sd.dish_id, sd.copies, COALESCE(d.name, sd.name) AS dish_name, d.stock AS dish_stock, d.status AS dish_status, c.status AS dish_category_status, c.type AS dish_category_type FROM setmeal_dish sd LEFT JOIN dish d ON d.id = sd.dish_id LEFT JOIN category c ON c.id = d.category_id WHERE sd.setmeal_id IN
#{id}
ORDER BY sd.setmeal_id, sd.dish_id
